% EXP_CV_NSTEP_TD_RACETRACK  Choose n for n-step TD control (n-step Sarsa) by
%   cross-validation over random seeds (Sutton & Barto 2018, Ch. 7; ESL 2nd ed.
%   Sec. 7.10 for cross-validation and the one-standard-error rule).
%
%   WHY SEEDS ARE THE FOLDS
%     In RL the "data" are generated by the agent itself, so a data set is a whole
%     training run. Independent runs = independent random seeds (behaviour noise,
%     acceleration failures). K-fold cross-validation therefore splits the SEEDS.
%
%   PROCEDURE
%     1. Train n-step Sarsa once for every (n, alpha, seed) in the grids below.
%        The best step size depends on n (S&B Fig. 7.2), so alpha is tuned per n.
%     2. Score each run on HELD-OUT evaluation episodes: its final greedy policy,
%        with the map's acceleration noise on and evaluation seeds different from
%        every training seed. Scores: mean return, success rate, and the area under
%        the training curve (mean training return).
%     3. Nested K-fold over seeds: in fold k, alpha*(n) is chosen on the other folds'
%        seeds only, then (n, alpha*(n)) is scored on fold k's seeds. CV(n) = mean over
%        folds, SE(n) = its standard error. Choosing and scoring on the same runs would
%        be optimistically biased.
%     4. n* = the smallest n with CV(n) >= max CV - SE (one-standard-error rule).
%
%   n-step TD CONTROL = n-step Sarsa (TDLearner 'Mode' "nstep", 'Target' "sarsa"):
%   off-policy n-step (Q-learning with n > 1) needs importance sampling or tree
%   backup, which TDLearner does not implement.
%
%   OUTPUT  Results/cv_nstep_td_<map>.mat (all scores, folds, choice) and .png
%
%   Author: Ocean Library | 2026-09-27

clear; clc; close all;
script_dir = fileparts(mfilename('fullpath'));
root = fullfile(script_dir, '..', '..', '..');
addpath(root);
out_dir = fullfile(script_dir, 'Results'); if ~isfolder(out_dir), mkdir(out_dir); end

%% Configuration (no hard-coded results: every number below is a setting)
cfg = struct();
cfg.Track        = "d_shape_with_shortcut";
cfg.Ns           = [1 2 4 8 16];            % candidate n
cfg.Alphas       = [0.05 0.1 0.2 0.4];      % step sizes tried for every n
cfg.Seeds        = 1:10;                    % independent training runs per (n, alpha)
cfg.Folds        = 5;                       % K (seeds are split into K folds)
cfg.Episodes     = 2000;                    % training episodes per run
cfg.Epsilon      = 0.1;                     % epsilon-greedy behaviour
cfg.Gamma        = 1.0;
cfg.InitialValue = -1000;                   % as in exp_compare_mc_vs_td_racetrack
cfg.MaxSteps     = [];                      % [] = the map's max_episode_steps (else 500)
cfg.EvalEpisodes = 50;                      % held-out evaluation episodes per run
cfg.EvalSeedBase = 100000;                  % evaluation seeds never overlap training seeds
cfg.Metric       = "evalReturn";            % "evalReturn" | "successRate" | "auc"
cfg.UseParallel  = true;                    % parfor when the Parallel Computing Toolbox is present
if ~isempty(getenv('OCEAN_QUICK'))          % smoke run
    cfg.Ns = [1 4]; cfg.Alphas = [0.1 0.4]; cfg.Seeds = 1:4; cfg.Folds = 2; cfg.Episodes = 200; cfg.EvalEpisodes = 5;
    out_dir = fullfile(out_dir, 'quick'); if ~isfolder(out_dir), mkdir(out_dir); end   % never overwrite real results
end

probe = OceanStats.RL.Env.Classic.RacetrackEnv(cfg.Track);
if ~probe.FinishReachable
    error('The finish of "%s" cannot be reached under %s movement.', cfg.Track, probe.MovementMode);
end
if isempty(cfg.MaxSteps)
    cfg.MaxSteps = 500; if isfinite(probe.MaxEpisodeSteps), cfg.MaxSteps = probe.MaxEpisodeSteps; end
end
evalFail = probe.FailProb;                  % held-out evaluation keeps the map's noise
fprintf('n-step Sarsa CV on %s (%s, speeds %d..%d, fail %.2f, cap %d)\n', cfg.Track, probe.MovementMode, ...
    probe.VelocityMin, probe.VelocityMax, probe.FailProb, cfg.MaxSteps);
if mod(numel(cfg.Seeds), cfg.Folds) ~= 0
    error('Seeds (%d) must split evenly into %d folds.', numel(cfg.Seeds), cfg.Folds);
end

%% 1-2. Train and score every (n, alpha, seed)
[NN, AA, SS] = ndgrid(1:numel(cfg.Ns), 1:numel(cfg.Alphas), 1:numel(cfg.Seeds));
jobs = [NN(:) AA(:) SS(:)]; J = size(jobs, 1);
evalReturn = zeros(J, 1); successRate = zeros(J, 1); auc = zeros(J, 1);
curves = zeros(J, cfg.Episodes); secs = zeros(J, 1);
usePar = cfg.UseParallel && ~isempty(ver('parallel')) && license('test', 'Distrib_Computing_Toolbox');
fprintf('%d runs (%d n x %d alpha x %d seeds), %d episodes each, parallel: %d\n', J, numel(cfg.Ns), ...
    numel(cfg.Alphas), numel(cfg.Seeds), cfg.Episodes, usePar);
tAll = tic;
if usePar
    parfor j = 1:J
        [evalReturn(j), successRate(j), auc(j), curves(j, :), secs(j)] = runOne(cfg, jobs(j, :), evalFail);
    end
else
    for j = 1:J
        [evalReturn(j), successRate(j), auc(j), curves(j, :), secs(j)] = runOne(cfg, jobs(j, :), evalFail);
        fprintf('  run %3d/%d  n=%-3d alpha=%-5.3g seed=%-3d  eval %8.1f  success %4.0f%%  (%.0f s)\n', j, J, ...
            cfg.Ns(jobs(j, 1)), cfg.Alphas(jobs(j, 2)), cfg.Seeds(jobs(j, 3)), evalReturn(j), 100 * successRate(j), secs(j));
    end
end
fprintf('All runs: %.0f s\n', toc(tAll));

score = struct('evalReturn', evalReturn, 'successRate', successRate, 'auc', auc).(cfg.Metric);
S = reshape(score, numel(cfg.Ns), numel(cfg.Alphas), numel(cfg.Seeds));      % S(n, alpha, seed)

%% 3. Nested K-fold cross-validation over seeds
nS = numel(cfg.Seeds); foldOf = repelem(1:cfg.Folds, nS / cfg.Folds);
foldOf = foldOf(randperm(RandStream('mt19937ar', 'Seed', 0), nS));          % seeds -> folds (recorded)
cvFold = zeros(numel(cfg.Ns), cfg.Folds); alphaPick = zeros(numel(cfg.Ns), cfg.Folds);
for k = 1:cfg.Folds
    tr = foldOf ~= k; te = foldOf == k;
    for i = 1:numel(cfg.Ns)
        [~, a] = max(mean(S(i, :, tr), 3));                                   % alpha*(n) on training seeds only
        alphaPick(i, k) = cfg.Alphas(a);
        cvFold(i, k) = mean(S(i, a, te));                                     % held-out score
    end
end
cv = mean(cvFold, 2); se = std(cvFold, 0, 2) / sqrt(cfg.Folds);
[best, ib] = max(cv);
nStar = cfg.Ns(find(cv >= best - se(ib), 1));                                 % one-standard-error rule
fprintf('\nCross-validated %s (mean +- SE over %d folds):\n', cfg.Metric, cfg.Folds);
for i = 1:numel(cfg.Ns)
    fprintf('  n = %-3d  %9.2f +- %.2f   alpha chosen per fold: %s\n', cfg.Ns(i), cv(i), se(i), mat2str(alphaPick(i, :)));
end
fprintf('Best mean: n = %d.  One-SE choice: n* = %d\n', cfg.Ns(ib), nStar);

%% 4. Save + figure (OceanViz)
res = struct('cfg', cfg, 'jobs', jobs, 'evalReturn', evalReturn, 'successRate', successRate, 'auc', auc, ...
    'curves', curves, 'seconds', secs, 'foldOf', foldOf, 'cvFold', cvFold, 'alphaPick', alphaPick, ...
    'cv', cv, 'se', se, 'nBest', cfg.Ns(ib), 'nStar', nStar);
save(fullfile(out_dir, "cv_nstep_td_" + cfg.Track + ".mat"), '-struct', 'res');

viz = OceanViz.Core('Theme', 'Dark'); C = viz.Colors;
fig = viz.createFigure('n-step TD cross-validation');
tl = tiledlayout(fig, 1, 3, 'Padding', 'compact', 'TileSpacing', 'compact');
ax1 = nexttile(tl); viz.styleAxes(ax1); hold(ax1, 'on');
errorbar(ax1, cfg.Ns, cv, se, '-o', 'Color', C.Primary, 'LineWidth', 2, 'MarkerFaceColor', C.Primary);
yline(ax1, best - se(ib), '--', 'best - 1 SE', 'Color', C.Grid, 'LabelHorizontalAlignment', 'left');
plot(ax1, nStar, cv(cfg.Ns == nStar), 'p', 'MarkerSize', 16, 'MarkerFaceColor', C.Boundary, 'MarkerEdgeColor', C.Boundary);
set(ax1, 'XScale', 'log', 'XTick', cfg.Ns); grid(ax1, 'on');
title(ax1, sprintf('CV %s vs n  (n* = %d)', cfg.Metric, nStar), 'Color', C.Text);
xlabel(ax1, 'n (steps in the return)'); ylabel(ax1, sprintf('held-out %s', cfg.Metric));
ax2 = nexttile(tl); viz.styleAxes(ax2);
imagesc(ax2, mean(S, 3)); colorbar(ax2, 'Color', C.Text); colormap(ax2, parula);
set(ax2, 'XTick', 1:numel(cfg.Alphas), 'XTickLabel', compose('%g', cfg.Alphas), 'YTick', 1:numel(cfg.Ns), ...
    'YTickLabel', compose('%d', cfg.Ns));
title(ax2, sprintf('mean %s over all seeds', cfg.Metric), 'Color', C.Text); xlabel(ax2, '\alpha'); ylabel(ax2, 'n');
ax3 = nexttile(tl); viz.styleAxes(ax3); hold(ax3, 'on');
cols = lines(numel(cfg.Ns)); w = max(1, round(cfg.Episodes / 50));
for i = 1:numel(cfg.Ns)
    [~, a] = max(mean(S(i, :, :), 3));
    sel = jobs(:, 1) == i & jobs(:, 2) == a;
    plot(ax3, movmean(mean(curves(sel, :), 1), w), 'Color', cols(i, :), 'LineWidth', 1.5, ...
        'DisplayName', sprintf('n = %d (\\alpha = %g)', cfg.Ns(i), cfg.Alphas(a)));
end
grid(ax3, 'on'); legend(ax3, 'Location', 'southeast', 'TextColor', C.Text, 'Color', C.Background);
title(ax3, 'training return (mean over seeds, smoothed)', 'Color', C.Text); xlabel(ax3, 'episode'); ylabel(ax3, 'return');
saveas(fig, fullfile(out_dir, "cv_nstep_td_" + cfg.Track + ".png"));
fprintf('Saved %s\n', fullfile(out_dir, "cv_nstep_td_" + cfg.Track + ".png"));

%% ---------------------------------------------------------------------------------
function [evalRet, success, aucVal, curve, secs] = runOne(cfg, job, evalFail)
% Train one n-step Sarsa run and score its final greedy policy on held-out episodes.
t0 = tic;
n = cfg.Ns(job(1)); alpha = cfg.Alphas(job(2)); seed = cfg.Seeds(job(3));
env = OceanStats.RL.Env.Classic.RacetrackEnv(cfg.Track);
env.setSeed(seed);
learner = OceanStats.RL.TD.TDLearner('Env', env, 'Task', "control", 'Mode', "nstep", 'N', n, ...
    'Target', "sarsa", 'StepSize', alpha, 'Exploration', cfg.Epsilon, 'Gamma', cfg.Gamma, ...
    'Episodes', cfg.Episodes, 'MaxSteps', cfg.MaxSteps, 'InitialValue', cfg.InitialValue, 'Seed', seed);
[~, ~, pi_, history] = learner.run();
curve = reshape(history.EpisodeReturns, 1, []);
aucVal = mean(curve);
% held-out evaluation: greedy policy, the map's noise, seeds disjoint from training
ev = OceanStats.RL.Env.Classic.RacetrackEnv(cfg.Track, 'FailProb', evalFail);
ev.setSeed(cfg.EvalSeedBase + seed);
rets = zeros(cfg.EvalEpisodes, 1); fin = false(cfg.EvalEpisodes, 1);
for e = 1:cfg.EvalEpisodes
    ev.reset(); G = 0;
    for t = 1:cfg.MaxSteps
        s = ev.CurrentState; k = ev.state_to_index(s);
        a = 5; if k > 0 && pi_(k) > 0, a = pi_(k); end
        valid = ev.get_valid_actions(s);
        if ~ismember(a, valid), a = valid(1); end
        [~, r, term] = ev.step(a);
        G = G + r;
        if term, fin(e) = true; break; end
    end
    rets(e) = G;
end
evalRet = mean(rets); success = mean(fin); secs = toc(t0);
end
